class AnthropicInputMessage(BaseModel):
    """
    One turn. A tool result is **a `tool_result` block inside a
    `user` message**, and a model's tool call comes back as a
    `tool_use` block inside an `assistant` message — Anthropic has
    no `tool` role, and that is the shape fact the translation turns
    on.

    **`system` is in the enum because a real client sends it, and
    the published contract says it does not.** Anthropic documents
    `user` and `assistant` only, and the first version of this
    schema said so. Then a real Claude Code driving a tool loop
    against this gateway was refused with
    `messages.1.role: Input should be 'user' or 'assistant'` on its
    very first request: it sends the documented top-level `system`
    (three blocks) **and, separately, a `system`-role message inside
    `messages`** carrying several more kilobytes, positioned after
    the first user turn.

    It is carried **in place** rather than hoisted into the leading
    system prompt. The client put it after a user turn deliberately,
    and moving it would change what the model sees for the sake of
    tidiness on a wire we do not own.

    This one was found by the live run and not by the unit tests,
    because the unit fixtures came from a capture of a *simple*
    request and this shape appears only once tools are in play.
    Recorded in `docs/acceptance/anthropic-messages-measurement.md`.

    """

    model_config = ConfigDict(
        extra='allow',
    )
    role: Role3
    content: str | list[AnthropicContentBlock] = Field(
        ...,
        description='A plain string, or a list of blocks. Both forms arrive from\nreal clients in the same conversation.\n',
    )


class AnthropicMessageResponse(BaseModel):
    """
    A completed message. The `x_eugene_plexus` envelope the OpenAI
    door adds to its response body is **not** here — it rides on
    response headers instead, because a strict Anthropic client is
    exactly who this door is for and an unknown top-level key is a
    risk with no upside.

    """

    id: str
    type: Type3
    role: Role4
    model: str = Field(
        ...,
        description='The model that actually answered, which after a cascade is\nnot necessarily the one that was asked for.\n',
    )
    content: list[AnthropicContentBlock] = Field(
        ...,
        description='`text` blocks and `tool_use` blocks, in the order the\nbackend produced them.\n',
    )
    stop_reason: StopReason | None = Field(
        None,
        description="Mapped from the backend's finish reason: `stop` becomes\n`end_turn`, `length` becomes `max_tokens`, `tool_calls`\nbecomes `tool_use`, and **since 2026-09-19 a backend's\n`content_filter` becomes `refusal`** — Anthropic's own name\nfor a classifier stopping the answer, so a client switching\non this field gets a value from the vocabulary it already\nparses rather than one we invented. Not verified against a\nlive Anthropic SDK; the OpenAI door's `content_filter` was.\n\nA backend error still reports `end_turn`, because there is\nno Anthropic stop reason for *the backend broke* and the\ntruncation is reported where it can be acted on — the log\nline and the metrics row.\n",
    )
    stop_sequence: str | None = None
    usage: AnthropicUsage | None = None


class MetricRequest(BaseModel):
    startedAt: AwareDatetime
    requestedModel: str
    servedModel: str | None = Field(
        None,
        description='What actually answered. Differs from the requested id after\na cascade.\n',
    )
    attempts: int = Field(..., ge=1)
    tier: int | None = Field(None, ge=1)
    totalMs: int = Field(
        ...,
        description='Gateway-side wall clock for the whole request, including\nfailed attempts and excluding the wake — the same figure\n`x_eugene_plexus.latency_ms` reports. Per-backend\nthroughput comes from `tries[].elapsedMs`, never from here.\n',
        ge=0,
    )
    routingMs: int | None = Field(
        None,
        description="Time spent deciding where to send this request - resolving\nthe model to a slot, picking a backend, and any\nrouting-table refresh that happened on the way - measured\n**before** `totalMs` starts and excluding the wake, which is\n`waitedMs`.\n\nPreviously invisible, and not always small: a refresh does\nHTTP to the agent and to every driver's `/v1/info`, inside\nthe request that triggered it.\n",
        ge=0,
    )
    refreshed: bool | None = Field(
        None,
        description='Whether a routing-table refresh ran inside this request.\nThe expensive and surprising case, so it is a flag rather\nthan something to infer from `routingMs`.\n',
    )
    strategy: str | None = Field(
        None,
        description='The `loadBalancing` value in effect when this request was\nrouted. Recorded per request because the config can change\nbetween them, and `least_busy` and `round_robin` explain\ndifferent orderings.\n',
    )
    candidates: list[MetricCandidate] | None = Field(
        None,
        description='What the balancer considered. Present only when there was a\ndecision to make - more than one candidate, or at least one\nrejected.\n',
    )
    waitedMs: int | None = Field(None, ge=0)
    swappedIn: bool | None = None
    streamed: bool | None = Field(
        None,
        description='Whether the client asked for SSE. Recorded because streamed\nrequests were invisible to the response envelope, and a\nstore that could not tell them apart would hide the very\ngap it was built to close.\n',
    )
    promptTokens: int | None = None
    completionTokens: int | None = None
    outcome: Outcome
    tries: list[MetricAttempt] = Field(..., min_length=1)


class MetricRequestPage(BaseModel):
    requests: list[MetricRequest]
    nextCursor: str | None = Field(None, description='Absent or null on the last page.')


class DriversInfo(BaseModel):
    drivers: list[DriverHealth] = Field(
        ...,
        description="Per-driver health snapshot, ordered as the gateway's\n`drivers` config declared them.\n",
    )


class MessageContent1(RootModel[list[TextContentPart | ImageContentPart]]):
    root: list[TextContentPart | ImageContentPart] = Field(
        ...,
        description='Text, null for an assistant tool-call turn, or ordered user content parts.\nImages are inline PNG/JPEG only: four per request, 5 MiB decoded each,\n10 MiB decoded total, 16 million pixels each, maximum dimension 8192.\nJSON bodies are limited to 16 MiB. Remote URLs are never fetched.\n',
        min_length=1,
    )


class DirectoryListing(BaseModel):
    """
    One directory on the component's own host, listed for a picker.

    Returned by `GET /v1/directories` on the library (whose host
    holds the model roots) and on the agent (whose host holds a
    path mapping's `to`, and any engine binary an operator points
    at). The same shape on both, because the UI has one picker and
    the only thing that differs is which machine's disk it is
    looking at — which is why `host` is on the response.

    This is the endpoint behind the promise `path_list` has carried
    since M2: *"an add/remove list of directory pickers"*. It lists
    what an operator could already type into a path field, on
    request, to the strongest credential there is; it is not a new
    capability and it is not a file browser.

    """

    host: str = Field(
        ...,
        description='The machine whose disk this is. On a multi-host install the\nanswer to "browse" is frequently a machine other than the\none the browser is on.\n',
    )
    path: str | None = Field(
        None,
        description='The directory listed, absolute and as this host spells it.\nAbsent when no `path` was asked for, in which case `entries`\nare the places to start from — every drive on Windows, `/`\non POSIX, and the home directory.\n',
    )
    parent: str | None = Field(
        None,
        description='The directory above `path`, so a picker can go up without\ndoing path arithmetic in a browser. Absent at a filesystem\nroot and when `path` is absent.\n',
    )
    entries: list[DirectoryEntry] = Field(
        ...,
        description='Sorted by name, directories first. Entries this component\nmay not read are omitted rather than failing the listing.\n',
    )


class ModelList(BaseModel):
    object: Literal['list']
    data: list[Model]


class ChatCompletionMessage(BaseModel):
    """
    OpenAI-shaped chat message. Intentionally *not* the shared
    `Message` schema: this one is on a wire contract we do not own,
    so it carries exactly OpenAI's fields and nothing of ours.
    Leaking a house field like `timestamp` into a payload an OpenAI
    SDK parses is how "compatible" quietly stops being true.

    """

    role: Role1
    content: str | MessageContent1 | None = Field(
        None,
        description='Text, null for an assistant tool-call turn, or ordered user content parts.\nImages are inline PNG/JPEG only: four per request, 5 MiB decoded each,\n10 MiB decoded total, 16 million pixels each, maximum dimension 8192.\nJSON bodies are limited to 16 MiB. Remote URLs are never fetched.\n',
    )
    name: str | None = Field(None, description='Optional participant name, per OpenAI.')
    tool_calls: list[ToolCall] | None = Field(
        None,
        description='Set on an **assistant** message, naming the tools the model\nchose to call. The caller executes them and replies with one\n`tool` message per call, each carrying the matching\n`tool_call_id`.\n',
    )
    tool_call_id: str | None = Field(
        None,
        description='Required on a **tool** message: which call in the preceding\nassistant turn this is the result of. `content` is the\nresult, as a string — the caller serializes it.\n',
    )


class ChatCompletionChoice(BaseModel):
    index: int
    message: ChatCompletionMessage
    finish_reason: FinishReason = Field(
        ...,
        description='`stop` for a natural end or a matched stop sequence,\n`length` for hitting the token cap, `tool_calls` when the\nmodel stopped because it wants one or more tools run,\n`content_filter` when a safety classifier stopped it.\n\n**`content_filter` is OpenAI\'s own value and is carried\nsince 2026-09-19.** Before that the chain was\n`content_filter` → the driver\'s `error` → `stop`, so a\nfiltered answer arrived as a natural end and a caller had\nno way to tell a refusal from a reply. The same mistake as\n`tool_calls` → `stop` before 2026-09-11, one value along:\na state with no row of its own reported as its nearest\nneighbour.\n\nUntil 2026-09-11 this enum was `stop` and `length` only, and\nits description said so in as many words — "OpenAI\'s two\nvalues for a completion **without** tool calls". That\nsentence was the single occurrence of the string "tool"\nanywhere in this contract or the driver\'s, and it was an\naccurate description of a control plane no agent harness\ncould use.\n',
    )


class ChatCompletionChunk(BaseModel):
    """
    One SSE frame of a streaming completion.
    """

    id: str
    object: Literal['chat.completion.chunk']
    created: int
    model: str
    choices: list[ChatCompletionChunkChoice]
    usage: CompletionUsage | None = None
    x_eugene_plexus: CompletionRoutingInfo | None = Field(
        None,
        description='Set on the **final frame only**, alongside `usage` — the\nsame place OpenAI puts its own end-of-stream extras.\nAbsent on every earlier frame, because the values are not\nknown until the completion is done.\n\nAdded at M8. Until then a streaming client could see no\nrouting information at all: the non-streaming response\ncarried this and the stream did not, so exactly the clients\nthat stream — the UI playground among them — were the ones\nthat could not tell which backend answered. Retained\nmetrics do not depend on this (they are recorded at the\nrouting hooks, which fire on both paths); this closes the\nmatching gap in what a caller can see.\n',
    )


class RoutingSlotView(BaseModel):
    model: str = Field(..., description='What a client asks for.')
    configured: bool | None = Field(
        None,
        description='True when a `modelSlots` entry exists for this model; false\nfor the implicit one-tier slot every served model id gets.\n',
    )
    tiers: list[RoutingTierView]


class AnthropicMessagesRequest(BaseModel):
    """
    Request body for `POST /v1/messages`, in Anthropic's shape.

    Measured Claude Code hints (`thinking`, `cache_control`,
    `context_management`) are accepted with a response header naming ignored
    settings. Metadata is discarded. Unknown top-level settings and top_k
    are explicitly rejected. This is a text/tool translation, not full parity.

    Consequently **this schema does not decide what is refused**.
    The refusals — image and document blocks, server-side tools,
    `mcp_servers`, more than four `stop_sequences` — are enforced
    against the raw request body by the implementation, with a 400
    naming the field, because a model that ignores extra keys cannot
    see the thing it is meant to reject. Read this schema as what
    the gateway *reads*, and the endpoint description as what it
    refuses.

    """

    model_config = ConfigDict(
        extra='allow',
    )
    model: str = Field(
        ...,
        description="A model id from `GET /v1/models`. Anthropic model names have\nno special meaning here: the id is resolved against this\ninstall's slots like any other, and a caller naming\n`claude-sonnet-4-5` gets whatever the operator mapped that\nto, or a 400.\n",
    )
    messages: list[AnthropicInputMessage] = Field(..., min_length=1)
    max_tokens: int = Field(
        ...,
        description="**Required by Anthropic's contract, and required here.**\nUnlike the OpenAI door, a missing value is a 400 rather than\na fill from the settings profile, because a client written\nagainst this wire always sends one and its absence means the\ncaller is not speaking this protocol.\n",
        ge=1,
    )
    system: str | list[AnthropicSystemBlock] | None = Field(
        None,
        description='A system prompt: a plain string, or a list of blocks.\n\nClaude Code sends three blocks, and the **first is not a\nprompt at all** — it is a billing header smuggled as prose\n(`x-anthropic-billing-header: …`). Any code that assumes\n`system[0]` is the instruction is wrong about the commonest\nclient. All blocks are concatenated in order into one\n`system` message.\n',
    )
    stream: bool | None = Field(
        False,
        description="When true the response is Anthropic's typed SSE stream.\n**Claude Code sets this on every request**, so the\nnon-streaming path of this endpoint is real but is not\nexercised by that client.\n",
    )
    temperature: float | None = Field(
        None,
        description="Anthropic's range is 0-1 where OpenAI's is 0-2. Passed\nthrough unscaled: the value means the same thing to a local\nengine either way, and rescaling would silently change what\na caller asked for.\n",
        ge=0.0,
        le=1.0,
    )
    top_p: float | None = Field(None, ge=0.0, le=1.0)
    top_k: int | None = Field(
        None,
        description='Unsupported. A non-null value returns 400 naming top_k. Before A2\nthis was silently discarded despite controlling generation.\n',
        ge=0,
    )
    stop_sequences: list[str] | None = Field(
        None,
        description='Up to four. A fifth is a 400 rather than a silent truncation\nto the first four, because dropping a stop sequence changes\nwhere the answer ends.\n',
    )
    tools: list[AnthropicToolDefinition] | None = Field(
        None,
        description='Tool definitions. Translated into the OpenAI function shape\nand carried to the backend unchanged.\n\nA backend that cannot carry tools is refused by name rather\nthan served without them — the same rule the OpenAI door\nstates, and for the same reason: a harness cannot tell "the\nmodel chose not to call one" from "nobody offered it any".\n',
    )
    tool_choice: AnthropicToolChoice | None = None
    metadata: dict[str, Any] | None = Field(
        None,
        description="Read and dropped. Claude Code puts a JSON *string* in\n`user_id` carrying a device id, an account uuid and a\nsession id; none of it is ours to keep, and the gateway's\nown request records already identify a request.\n",
    )
    thinking: dict[str, Any] | None = Field(
        None,
        description='**Read and dropped, never refused**, and the distinction was\nmeasured. Present on every Claude Code request, in three\nshapes: `{"budget_tokens": N, "type": "enabled"}` for a\nknown Claude id, `{"type": "adaptive"}` for an arbitrary\nlocal id, and **`null` when the caller set\n`MAX_THINKING_TOKENS=0`** — so even `"thinking" in body` is\ntrue for the one configuration asking for no thinking at\nall.\n\nThis is a compatibility concession, not enforcement of the caller\'s\nreasoning budget. Non-null values are disclosed on the ignored-settings\nresponse header. The operator\'s profile governs local thinking behavior.\n',
    )
    cache_control: dict[str, Any] | None = Field(
        None,
        description='Prompt-cache hints, read and dropped wherever they appear —\non system blocks, on the last user content block, and on\n`tool_result` blocks. A local engine owns its own KV cache\nand there is nothing here to honour.\n',
    )


class Message(BaseModel):
    """
    A single message in a conversation. Deliberately close to the
    OpenAI / Anthropic chat message format so drivers don't have to
    re-shape on every hop.

    """

    role: Role
    content: str | MessageContent1 | None = Field(
        None,
        description='Text, null for an assistant tool-call turn, or ordered user content parts.\nImages are inline PNG/JPEG only: four per request, 5 MiB decoded each,\n10 MiB decoded total, 16 million pixels each, maximum dimension 8192.\nJSON bodies are limited to 16 MiB. Remote URLs are never fetched.\n',
    )
    toolCalls: list[dict[str, Any]] | None = Field(
        None,
        description="On an **assistant** message: the tool calls the model made,\nin OpenAI's `{id, type, function: {name, arguments}}` shape.\n\nDeliberately loose here. This is the *shared* schema, so a\ntightly-typed copy would be a third definition of the same\nobject alongside the gateway's and the driver's, and the one\nplace all three must agree is the wire format, which is\nOpenAI's and not ours to restate. The two API documents\ncarry the strict shapes.\n",
    )
    toolCallId: str | None = Field(
        None,
        description='On a **tool** message: which call this is the result of.\n`content` is the result, serialized by the caller.\n',
    )
    timestamp: AwareDatetime | None = Field(
        None, description='When the message was produced. Server-assigned if omitted.'
    )


class ChatCompletionRequest(BaseModel):
    """
    Supported chat settings only. Unknown properties, including nested message,
    tool and response-format properties, return 400 with a field name. Arbitrary
    JSON Schemas inside function parameters and response schemas are preserved.
    Validation errors do not echo request values. See docs/api-compatibility.md.

    """

    model_config = ConfigDict(
        extra='forbid',
    )
    model: str = Field(
        ...,
        description='A model id from `GET /v1/models`. The gateway resolves it to\na backend; the client does not choose a backend.\n',
    )
    messages: list[ChatCompletionMessage] = Field(..., min_length=1)
    max_tokens: int | None = Field(
        None,
        description="Positive JSON integer generation limit; booleans, strings and floats\nare rejected. Null or absent uses the profile then gateway default.\nNormalized before defaults and preserved on every fallback attempt.\nEngine token accounting is not guaranteed to match OpenAI's.\n",
        ge=1,
    )
    max_completion_tokens: int | None = Field(
        None,
        description='Alias of max_tokens. If both are non-null they must be equal, otherwise\n400 names max_completion_tokens. Neither spelling takes precedence over\na conflicting value. This does not add reasoning-token support to engines.\n',
        ge=1,
    )
    temperature: float | None = Field(None, ge=0.0, le=2.0)
    top_p: float | None = Field(
        None,
        description='Nucleus sampling cutoff, carried to the backend.\n\n**This field was accepted, validated and discarded until\n2026-09-19**: `GenerateRequest` had no `topP` to put it in,\nso the value went no further than this schema and nothing\nwas logged. It has one now.\n',
        ge=0.0,
        le=1.0,
    )
    stop: str | Stop | None = Field(
        None,
        description='One stop sequence or up to four sequences; forwarded as an array.',
    )
    seed: int | None = Field(
        None,
        description='Passed through to backends that support deterministic\nsampling; dropped with a warning where they do not.\n\n**True since 2026-09-19 and unfulfillable before it** —\nthere was no `seed` on `GenerateRequest`, so the value was\ndropped by every backend and the warning this sentence\npromises was logged by none of them. A caller asking for a\nseed is asking for a reproducible answer and was getting a\ndifferent one each time, with nothing in the response to\nsay so.\n',
    )
    stream: bool | None = Field(
        False,
        description='When true the response is an SSE stream of\n`ChatCompletionChunk` objects terminated by `data: [DONE]`.\n',
    )
    user: str | None = Field(
        None,
        description='Ignored client annotation; not stored, forwarded or used as identity.',
    )
    metadata: dict[str, str] | None = Field(
        None,
        description='Ignored annotations; not provider storage or queryable metadata.',
    )
    safety_identifier: str | None = Field(
        None, description='Ignored annotation; not an authenticated user identity.'
    )
    n: Literal[1] = Field(
        1,
        description='Only one completion is supported; any other non-null value returns 400.',
    )
    logprobs: Literal[False] = Field(
        False,
        description='Only false is supported; log probabilities are not implemented.',
    )
    store: Literal[False] = Field(
        False,
        description='Only false is supported; provider completion storage is not implemented.',
    )
    stream_options: StreamOptions | None = Field(
        None,
        description="With streaming, true adds a usage-only chunk before DONE when the driver\nreports usage. False omits usage. If absent, retains Eugene's historical\nfinal choice chunk containing usage. Does not affect retained metrics.\n",
    )
    tools: list[Tool] | None = Field(
        None,
        description='Tools the model may call. Passed through to the backend\nunchanged; the gateway never invents, filters or reorders\nthem.\n\n**The gateway does not execute tools.** It carries the\ndefinitions down and the model\'s chosen calls back up, and\nthe caller runs them and sends the results as `tool` role\nmessages. That is OpenAI\'s contract and it is the one an\nagent harness implements.\n\nA backend that cannot carry tools is not silently stripped:\nthe request fails with a 400 naming the backend, because a\nharness that receives a plain answer where it expected a\ntool call has no way to tell "the model chose not to" from\n"nobody ever offered it the tools" — and the second is a\nbug that looks exactly like the first. `GET /v1/models`\nreports which models can.\n',
    )
    tool_choice: ToolChoice | NamedToolChoice | None = Field(
        None,
        description='How the model should use `tools`. `auto` is the default when\ntools are present, `none` forbids calling one, `required`\nforces at least one call, and an object names a specific\nfunction. Passed through; the gateway does not enforce it.\n',
    )
    response_format: ResponseFormat | None = None


class ChatCompletionResponse(BaseModel):
    id: str = Field(
        ..., description='Completion id, `chatcmpl-` prefixed as clients expect.'
    )
    object: Literal['chat.completion']
    created: int
    model: str = Field(
        ...,
        description='The model that actually served the request. Equal to the\nrequested id in the normal case; after a cascade it names\nwhat answered, which may differ.\n',
    )
    choices: list[ChatCompletionChoice]
    usage: CompletionUsage | None = Field(
        None, description='Present on the final chunk only.'
    )
    x_eugene_plexus: CompletionRoutingInfo | None = None


class RoutingTableView(BaseModel):
    """
    The gateway's resolved routing table, as of the last refresh.
    The same snapshot requests are routed from, opened up so an
    operator can see why a request went where it did.

    """

    refreshed_at: AwareDatetime
    load_balancing: str | None = Field(
        None, description='The strategy in effect — the `loadBalancing` config value.'
    )
    slots: list[RoutingSlotView]
    unreachable_drivers: list[str] | None = Field(
        None, description='Drivers in the topology that did not answer `/v1/info`.'
    )
    control_root: ControlRootView | None = None


